-- Fixtures for the Google Play listing screenshots (e2e/smoke/22-play-listing-frames.yaml). Applied by
-- the CI ui-smoke / ui-full jobs on the throw-away local Supabase after seed-e2e.sql and seed-break.sql.
-- Never run this on the hosted project.
--
-- Everything belongs to one extra account, demo@test.local ("Ravi Kumar", …000d01), so nothing in
-- Sree's Home, My players, New game candidates or Results changes for the other flows. His nine
-- placeholders (…000d11 – …000d19) carry ordinary names so the store pictures do not read "Test Alpha".
--   L  …000d01  GAMEL1  Points, active, 10 players x 8 rounds           -> the sideways scorecard (Sree, Nov 19: "do an example of 10")
--   M  …000d02  GAMEM1  Pool 101, active, 9 players x 5 rounds, 2 out    -> the pool portrait
--   N1 …000d03  GAMEN1  Points, completed, closed, label S1, 6 x 3 rounds }
--   N2 …000d04  GAMEN2  Points, completed, closed, label S2, 6 x 3 rounds } -> saved result …000d01 over S1 + S2
-- Generated once by hand (Nov 19); plain inserts so the numbers are visible here.

                        raw_app_meta_data, raw_user_meta_data, created_at, updated_at)
values ('00000000-0000-0000-0000-000000000000', '00000000-0000-4000-8000-000000000d01', 'authenticated', 'authenticated',
        'demo@test.local', crypt('123456', gen_salt('bf')), now(), '{"provider":"email","providers":["email"]}',
        '{"display_name":"Ravi Kumar","first_name":"Ravi","last_name":"Kumar"}', now() - interval '20 days', now());

do $$
begin
  if exists (select 1 from information_schema.columns where table_schema = 'auth' and table_name = 'users' and column_name = 'confirmation_token') then
    update auth.users
       set confirmation_token = coalesce(confirmation_token, ''), recovery_token = coalesce(recovery_token, ''),
           email_change = coalesce(email_change, ''), email_change_token_new = coalesce(email_change_token_new, ''),
           email_change_token_current = coalesce(email_change_token_current, ''), phone_change = coalesce(phone_change, ''),
           phone_change_token = coalesce(phone_change_token, ''), reauthentication_token = coalesce(reauthentication_token, ''),
           is_sso_user = coalesce(is_sso_user, false), is_anonymous = coalesce(is_anonymous, false)
     where email = 'demo@test.local';
  end if;
  if exists (select 1 from information_schema.tables where table_schema = 'auth' and table_name = 'identities') then
    select gen_random_uuid(), u.id, u.id::text, 'email',
           jsonb_build_object('sub', u.id::text, 'email', u.email, 'email_verified', true, 'phone_verified', false),
           now(), u.created_at, now()
      from auth.users u where u.email = 'demo@test.local'
       and not exists (select 1 from auth.identities i where i.user_id = u.id);
  end if;
end $$;



-- Game L: Points, 10 players, 8 rounds (round n's winner takes the pot as rummy; the deal goes round by seat).
values ('10000000-0000-4000-8000-000000000d01', '00000000-0000-4000-8000-000000000d01', 'active', 'stake', '{"gameType":"stake","expenseEnabled":false,"expenseAmount":0,"stakeDrop":-10,"stakeMiddleDrop":-30,"maxCount":-80}', 'GAMEL1', now() - interval '110 minutes', 9);

