values ('10000000-0000-4000-8000-000000000d02', '00000000-0000-4000-8000-000000000d01', 'active', 'pool', '{"gameType":"pool","expenseEnabled":false,"stakeDrop":25,"stakeMiddleDrop":50,"dropAmount":25,"mdAmount":50,"maxCount":80,"poolLimit":101,"reentry":true,"reentryPlus":1,"lateEntryPlus":1,"seatingPrompted":true}', 'GAMEM1', now() - interval '80 minutes', 6);
select public.pool_recompute('10000000-0000-4000-8000-000000000d02');

